const VALID_STATUS_FILTERS = ['upcoming', 'draft', 'completed', 'all'] as const
type ValidStatusFilter = (typeof VALID_STATUS_FILTERS)[number]

export default async function FlashEventsPage({ searchParams }: Props) {
  await requirePersona(['studio_owner'])
  const auth = await getAuthenticatedUser()
  if (!auth) redirect('/login')

  const params = await searchParams
  const statusParam = typeof params.status === 'string' ? params.status : 'upcoming'

  // Redirect legacy filter values to their canonical equivalents
  if (statusParam === 'published') redirect('/flash-events?status=upcoming')
  if (statusParam === 'cancelled') redirect('/flash-events?status=all')

  const filter: ValidStatusFilter = VALID_STATUS_FILTERS.includes(statusParam as ValidStatusFilter)
    ? (statusParam as ValidStatusFilter)
    : 'upcoming'

